  "在「入住管理」找到该长辈，在操作栏点击「办理试住」，核对床位、日期和费用。操作栏的「试住」可查看记录。已在试住的长辈可从同一栏办理正式入住或取消入住，回访报告在同页填写。": "Find the person in Admissions and choose Start trial stay. Verify the bed, dates and fees. View the trial and confirm or cancel admission from the same row. Record follow-up on that page.",
  "在「床位管理 → 全部床位」选择楼栋、楼层和床位状态，也可切换楼层平面图。可以请健康助理打开床位管理并筛选具体楼栋。": "Open Bed management → All beds. Select the building, floor and bed status, or switch to the floor plan. You can also ask the health assistant to open Bed management filtered to a named building.",
  "在「照护服务 → 班次交接」选择接班账号和交班范围，填写未完成事项并提交。接班人可从顶部待处理事项打开交班，核对后签收。": "Open Care services → Shift handover. Select the receiving employee and scope, enter outstanding matters and submit. The recipient opens the pending handover, reviews it and acknowledges receipt.",
