  "在登录页进入「首次设置 / 找回密码」，使用已绑定的邮箱或手机接收验证码。联系方式无法使用时，请联系负责账号管理的人员处理。": "Choose Set or reset password on the sign-in page. Request a verification code using the email address or mobile number linked to the account. Contact the account administrator if that method is unavailable.",
