  "要整批派发照护工单，请进入「照护服务 → 定时工单」，点击「新建定时计划」，设置工单类型、执行时间和对象，核对并启用。到时系统会派发，可在「今日派发」查看批次。在「系统内置周期任务」可查看其他自动任务的状态和入口。\n\n经营月报和民政报送在「机构运营 → 统计报送」。经营月报按所选月份汇总，民政报送草稿需经办人生成。自动巡查简报和站内推送由 Owner 在「机构设置 → 定时巡查」配置。平台目前没有把这些内容统一批量发送的入口。": "In Care services open Scheduled tickets & batch dispatch and create a schedule. Set the type, time and recipients, review the plan and enable it. The system dispatches at the scheduled time. Check today’s batches and the built-in scheduled jobs list.\n\nMonthly operating reports and statutory submissions are in Reports. Select the month for an operating report or generate a statutory draft. The Owner configures automated rounds and in-app notifications in Facility settings. Each reporting workflow has its own delivery action.",
